actions.script:
const ruleSet = ec.entity.find("moqui.device.DeviceRuleSet").condition("deviceRuleSetId", deviceRuleSetId).one();
if (!ruleSet) {
    ec.message.addError(`DeviceRuleSet ${deviceRuleSetId} not found.`);
    return;
}
const ruleSetName = ruleSet.ruleSetName || deviceRuleSetId;
const nonEmpty = (value) => value != null && value !== '' ? String(value) : null;
// a decimal field is a Decimal object in the script: toNumber() reads it
const toNumber = (value) => value != null && typeof value.toNumber === 'function' ? value.toNumber() : Number(value);
const bufferModes = {PpcmPlcAborting: '0', PpcmPlcBuffered: '1', PpcmPlcBlendingLow: '2',
    PpcmPlcBlendingPrev: '3', PpcmPlcBlendingNext: '4', PpcmPlcBlendingHigh: '5'};
const transitionModes = {PpcmPlcTMNone: '0', PpcmPlcTMCornerDist: '1', PpcmPlcTMConstVel: '2',
    PpcmPlcTMStartVel: '3', PpcmPlcTMMaxVel: '4'};

// priority -> {lines: [[name, value]], parameterIds: Set, pointCount}
const groups = new Map();
const group = (priority) => {
    const key = priority == null ? 0 : toNumber(priority);
    if (!groups.has(key)) groups.set(key, {lines: [], parameterIds: new Set(), pointCount: 0});
    return groups.get(key);
};

let ruleFind = ec.entity.find("moqui.device.DeviceRule").condition("deviceRuleSetId", deviceRuleSetId);
if (deviceId) ruleFind = ruleFind.condition("deviceId", deviceId);
if (deviceRuleId) ruleFind = ruleFind.condition("deviceRuleId", deviceRuleId);
for (const rule of (ruleFind.list() || [])) {
    if (!rule.deviceConfigId) continue;
    const config = ec.entity.find("moqui.device.DeviceConfig").condition("deviceConfigId", rule.deviceConfigId).one();
    if (!config) continue;
    const physical = rule.deviceId ?
        ec.entity.find("moqui.device.PhysicalDevice").condition("deviceId", rule.deviceId).one() : null;
    const deviceName = nonEmpty(physical?.deviceName) || rule.deviceId;
    const g = group(rule.priority);

    const parameters = ec.entity.find("moqui.math.Parameter").condition("deviceConfigId", config.deviceConfigId).list();
    for (const p of (parameters || [])) {
        if (g.parameterIds.has(p.parameterId)) continue;
        const def = ec.entity.find("moqui.math.ParameterDef").condition("parameterDefId", p.parameterDefId).one();
        if (!def) continue;
        g.parameterIds.add(p.parameterId);
        let itemName = null;
        for (const item of (ec.entity.find("moqui.device.DeviceRequestItem").condition("parameterId", p.parameterId).list() || [])) {
            if (item.requestItemName != null && (itemName == null || item.requestItemName > itemName)) itemName = item.requestItemName;
        }
        const alias = nonEmpty(p.parameterAlias);
        const type = config.deviceTypeEnumId || '';
        let name = nonEmpty(itemName);
        if (name == null) {
            if (type === 'DtPLC') name = 'dev.' + (alias || def.parameterName);
            else if (type.startsWith('DtMoquiPlc')) name = 'dev.' + deviceName + '.' + (alias || def.parameterName);
            else name = alias || (deviceName + '.' + def.parameterName);
        }
        const value = p.numericValue != null ? String(p.numericValue) :
            (p.parameterEnumId != null ? p.parameterEnumId : p.symbolicValue);
        g.lines.push([name, value ?? '']);
    }

    const functionId = config.approximatedFunctionId;
    if (!functionId) continue;
    g.lines.push(['Trajectory.trajectoryId', String(functionId)]);
    const points = ec.entity.find("moqui.math.TrajectoryPoint").condition("approximatedFunctionId", functionId).list();
    for (const point of (points || [])) {
        const sample = ec.entity.find("moqui.math.ApproximatedFunctionSample")
            .condition("approximatedFunctionId", functionId)
            .condition("approximatedFunctionSampleId", point.approximatedFunctionSampleId).one();
        if (!sample) continue;
        g.pointCount++;
        const prefix = `Trajectory.points[${toNumber(sample.sequenceNum) - 1}]`;
        if (sample.sampleVectorId) {
            for (const comp of (ec.entity.find("moqui.math.VectorComponent").condition("vectorId", sample.sampleVectorId).list() || [])) {
                g.lines.push([`${prefix}.pos.v[${comp.dimensionIndex}]`, String(comp.realValue)]);
            }
        }
        g.lines.push([`${prefix}.sequenceNum`, String(sample.sequenceNum)]);
        g.lines.push([`${prefix}.timeOffsetMs`, point.pointTimeOffsetMillis != null ? String(point.pointTimeOffsetMillis) : '0.0']);
        g.lines.push([`${prefix}.isBreakPoint`, point.isBreakPoint === 'Y' ? 'TRUE' : 'FALSE']);
        g.lines.push([`${prefix}.hasBlendingOverride`, point.blendingEnumId != null ? 'TRUE' : 'FALSE']);
        g.lines.push([`${prefix}.bufferMode`, bufferModes[point.blendingEnumId] ?? '3']);
        g.lines.push([`${prefix}.transitionMode`, transitionModes[point.blendingEnumId] ?? '0']);
        const pathPoint = ec.entity.find("moqui.math.ParametricPathPoint")
            .condition("approximatedFunctionId", functionId)
            .condition("approximatedFunctionSampleId", point.approximatedFunctionSampleId).one();
        g.lines.push([`${prefix}.blendingMode`, pathPoint?.tolerance != null ? String(pathPoint.tolerance) : '0.0']);
    }
}

files = [];
rowCount = 0;
for (const priority of [...groups.keys()].sort((a, b) => a - b)) {
    const g = groups.get(priority);
    if (g.pointCount > 0) g.lines.push(['Trajectory.pointCount', String(g.pointCount)]);
    if (g.lines.length === 0) continue;
    g.lines.sort((a, b) => a[0] < b[0] ? -1 : (a[0] > b[0] ? 1 : 0));
    files.push({
        name: `${ruleSetName}_p${String(priority).padStart(2, '0')}.txt`,
        content: g.lines.map(([name, value]) => `${name}:=${value}`).join('\n'),
        priority: priority,
        rowCount: g.lines.length
    });
    rowCount += g.lines.length;
}
